argv:
$ErrorActionPreference='Stop'
$work='E:\PC-Control\Proxifier-Avito-20261012'
$original=Join-Path $env:APPDATA 'Proxifier4\Profiles\Default.ppx'
$backup=Join-Path $work 'Default-original-backup.ppx'
if(!(Test-Path -LiteralPath $backup) -or (Get-FileHash $original).Hash -ne (Get-FileHash $backup).Hash){throw 'BACKUP_MISMATCH_DO_NOT_MODIFY'}
$chrome=@(Get-CimInstance Win32_Process -Filter "Name='chrome.exe'")
$main=$chrome|Where-Object {$_.ProcessId -eq 16760 -and $_.CommandLine -match 'remote-debugging-port=17410'}
$second=$chrome|Where-Object{$_.ProcessId -eq 9148 -and $_.CommandLine -notmatch '--type='}
$test=$chrome|Where-Object{$_.ProcessId -eq 9316 -and $_.CommandLine -match 'remote-debugging-port=17447'}
if(!$main -or !$second -or !$test){throw 'BROWSER_PROCESS_IDENTITIES_CHANGED_DO_NOT_MODIFY'}
$roots=@(9148,9316)
$extra=@($chrome|Where-Object {$roots -contains $_.ParentProcessId})
$pids=@($roots+@($extra|Select-Object -ExpandProperty ProcessId)|Sort-Object -Unique)
$apps=($pids|ForEach-Object{"pid=$_"}) -join ';'
$txt=[System.IO.File]::ReadAllText($original,[System.Text.Encoding]::UTF8)
$rx=[regex]::Match($txt,'<RuleList(?:\s[^>]*)?>')
if(!$rx.Success -or ([regex]::Matches($txt,'<RuleList(?:\s[^>]*)?>').Count -ne 1)){throw 'UNKNOWN_RULELIST_SCHEMA'}
$rule=([Environment]::NewLine)+'    <Rule enabled="true">'+([Environment]::NewLine)+'      <Action type="Direct" />'+([Environment]::NewLine)+'      <Applications>'+$apps+'</Applications>'+([Environment]::NewLine)+'      <Name>Second Chrome DIRECT [session]</Name>'+([Environment]::NewLine)+'    </Rule>'
$proposed=$txt.Insert($rx.Index+$rx.Length,$rule)
$staged=Join-Path $work 'SecondChrome-Direct-PIDs.ppx'
[System.IO.File]::WriteAllText($staged,$proposed,[System.Text.UTF8Encoding]::new($false))
[xml]$oldxml=$txt;[xml]$newxml=$proposed
$oldNames=@($oldxml.SelectNodes('//*[local-name()="Rule"]/Name')|ForEach-Object{$_.InnerText})
$newNames=@($newxml.SelectNodes('//*[local-name()="Rule"]/Name')|ForEach-Object{$_.InnerText})
if(($newNames.Count -ne ($oldNames.Count+1)) -or ($newNames[0] -ne 'Second Chrome DIRECT [session]') -or (($newNames|Select-Object -Skip 1) -join '|' -ne ($oldNames -join '|'))){throw 'RULE_INSERTION_INVALID'}
foreach($tag in @('Options','ProxyList','ChainList')){if($oldxml.DocumentElement.SelectSingleNode($tag).OuterXml -cne $newxml.DocumentElement.SelectSingleNode($tag).OuterXml){throw "PROXY_CONFIG_CHANGED_$tag"}}
if($proposed.Replace($rule,'') -cne $txt){throw 'ORIGINAL_XML_NOT_PRESERVED'}
$o=[ordered]@{status='STAGED_VALIDATED_NOT_APPLIED';stagedPath=$staged;backupExists=$true;ruleName=$newNames[0];scope='only second-Chrome and isolated-test Chrome current PIDs';mainChromePid=16760;newRulePidCount=$pids.Count;priorRuleNames=$oldNames;oldRuleCount=$oldNames.Count;newRuleCount=$newNames.Count;proxyServerChainAndOptionsUnchanged=$true;originalDefaultRuleStillLast=($newNames[-1] -eq 'Default')}
$o|ConvertTo-Json -Compress -Depth 5
